import {esc,icon,button,badge,empty} from './ui.js';
import {money,dateLabel,uid} from './data.js';
import {goalProgress} from './goals.js';
const choices=(values,current)=>values.map(([v,label])=>`<option value="${esc(v)}" ${v===String(current)?'selected':''}>${esc(label)}</option>`).join('');
export function createManualUI(api){let tab='active';const eligible=()=>api.accounts().filter(a=>a.status==='Active').sort((a,b)=>(b.userId===api.ownerId())-(a.userId===api.ownerId()));
 const active=()=>api.trades().filter(t=>t.source==='Manual entry'),archived=()=>api.archived();const records=()=>tab==='active'?active():archived();
 function page(){const rows=[...records()].sort((a,b)=>(b.date+b.time).localeCompare(a.date+a.time)),net=active().reduce((sum,t)=>sum+t.pnl-t.fees,0);return `<div class="page-heading"><div><span class="eyebrow">YOUR EXECUTION. YOUR RECORD.</span><h1>Manual trades<span class="gold-text">.</span></h1><p>Record closed trades with the detail your next review deserves.</p></div><div class="page-actions">${button('Add trade','manual-new','primary','plus')}</div></div><div class="manual-module-note">${icon('shield')}<span>Manual entries join your calendar, analytics, and account goals. They are clearly labeled and never change broker-synced executions.</span></div><div class="manual-summary"><div><span>Manual trades in this view</span><strong>${active().length}</strong></div><div><span>Net result after costs</span><strong class="${net>=0?'positive-text':'negative-text'}">${money(net,true)}</strong></div><div><span>Archived entries</span><strong>${archived().length}</strong></div></div><section class="panel"><div class="panel-heading"><h3>Your manual entries</h3><div class="segmented"><button data-action="manual-tab:active" class="${tab==='active'?'active':''}">Active</button><button data-action="manual-tab:archived" class="${tab==='archived'?'active':''}">Archived</button></div></div>${rows.length?`<div class="table-scroll"><table><thead><tr><th>Trade</th><th>Account</th><th>Closed</th><th>Quality</th><th>Net P&L</th><th>R</th><th>Actions</th></tr></thead><tbody>${rows.map(t=>`<tr><td><strong>${esc(t.symbol)}</strong><small class="block muted">${esc(t.side)} · ${t.lots} lots · ${esc(t.ticket)}</small></td><td>${esc(api.accounts().find(a=>a.id===t.accountId)?.name||'Account')}</td><td>${dateLabel(t.date)}<small class="block muted">${esc(t.time)}</small></td><td>${badge(t.grade||'Not graded','neutral')}</td><td class="number ${t.pnl-t.fees>=0?'positive-text':'negative-text'}">${money(t.pnl-t.fees,true)}</td><td>${t.r==null?'—':t.r.toFixed(2)+'R'}</td><td><div class="flex gap">${tab==='active'?button('Edit','manual-edit:'+t.id,'secondary compact','edit')+button('Archive','manual-archive:'+t.id,'text compact','trash'):button('Restore','manual-restore:'+t.id,'secondary compact','refresh')}</div></td></tr>`).join('')}</tbody></table></div>`:empty(tab==='active'?'A clear record starts here.':'No archived manual trades',tab==='active'?'Add your first closed trade. Your account balance and insights will update after saving.':'Archived entries can be restored without retyping the execution.',tab==='active'?button('Add your first trade','manual-new','primary','plus'):'')}</section>`;}
 function open(tradeId){const existing=tradeId?api.db().trades.find(t=>t.id===tradeId):null;if(tradeId&&(!existing||existing.source!=='Manual entry'||!api.accounts().some(a=>a.id===existing.accountId)))return;const accounts=eligible();if(!accounts.length){api.modal('An active account is needed',`<p>Create or restore a trading account in Accounts & licenses before recording a trade.</p>`,button('Close','close','secondary'));return;}
 const a=accounts.find(a=>a.id===existing?.accountId)||accounts.find(a=>a.id===api.selectedAccount())||accounts[0];if(existing&&!accounts.some(a=>a.id===existing.accountId)){api.toast('This account is inactive. Restore it before editing.');return;}const g=a.goal?goalProgress(a,api.db().trades):null,t=existing||{accountId:a.id,grade:'',side:'Buy',fees:0,risk:g&&!g.complete?g.risk:'',session:'Unclassified'},input=(name,label,value,attrs='')=>`<label>${label}<input name="${name}" value="${esc(value??'')}" ${attrs}></label>`;
 api.modal(existing?'Edit manual trade':'Record a closed trade',`<form id="manual-trade-form" data-id="${esc(existing?.id||'')}"><input type="hidden" name="requestId" value="${uid()}"><input type="hidden" name="revision" value="${existing?.revision||1}"><div class="manual-form-intro"><span class="manual-form-icon">${icon('edit')}</span><div><strong>Every detail makes the review clearer.</strong><p>Enter the actual execution and broker-reported P&L. Times stay in the account’s reporting time.</p></div></div><div id="manual-form-error" class="import-error" role="alert" hidden></div><label>Trading account<select name="accountId" id="manual-account" ${existing?'disabled':''}>${choices(accounts.map(a=>[a.id,a.name+' · '+(api.db().users.find(u=>u.id===a.userId)?.name||'')]),t.accountId)}</select></label>${existing?`<input type="hidden" name="accountId" value="${esc(t.accountId)}">`:''}<div class="manual-section-label">01 / EXECUTION</div><div class="form-grid">${input('symbol','Instrument',t.symbol,'required maxlength="30" placeholder="e.g. XAUUSD"')}<label>Direction<select name="side">${choices([['Buy','Buy / Long'],['Sell','Sell / Short']],t.side)}</select></label>${input('lots','Position size (lots)',t.lots,'type="number" min="0.000001" max="1000000" step="any" required placeholder="0.10"')}${input('brokerTicket','Broker position ticket · optional',t.brokerTicket,'maxlength="40" placeholder="Leave blank for an automatic reference"')}${input('openTime','Opened · reporting time',t.openTime?.slice(0,19),'type="datetime-local" step="1" required')}${input('closeTime','Closed · reporting time',t.closeTime?.slice(0,19),'type="datetime-local" step="1" required')}${input('entry','Entry price',t.entry,'type="number" min="0.00000001" step="any" required')}${input('exit','Exit price',t.exit,'type="number" min="0.00000001" step="any" required')}${input('stopLoss','Initial stop loss · optional',t.stopLoss,'type="number" min="0.00000001" step="any"')}${input('takeProfit','Take profit · optional',t.takeProfit,'type="number" min="0.00000001" step="any"')}</div><div class="manual-section-label">02 / RESULT & RISK</div><div class="form-grid">${input('pnl','Gross profit / loss (USD)',t.pnl,'type="number" step="0.01" required placeholder="Signed result before costs"')}${input('fees','Costs & swaps (USD)',t.fees,'type="number" step="0.01"')} ${input('risk','Initial risk (USD) · optional',t.risk,'type="number" min="0.01" step="0.01"')}<label>Setup quality<select name="grade">${choices([['','Not graded'],['A+','A+'],['A','A'],['B','B'],['C','C']],t.grade)}</select></label></div><p class="manual-input-hint">Positive costs reduce profit; enter a negative cost for a net swap credit. Net P&L and R are calculated after costs. Check the position ticket to avoid duplicating an imported trade.</p><div id="manual-result-preview" class="manual-result-preview" aria-live="polite"></div><div class="manual-section-label">03 / REVIEW</div><label>Trading session<select name="session">${choices(['Unclassified','Asia','London','New York'].map(x=>[x,x]),t.session)}</select></label><label>Execution notes<textarea name="notes" rows="3" maxlength="10000" placeholder="What made this setup A+? What would you repeat or improve?">${esc(t.notes||'')}</textarea></label><label class="checkbox-label"><input type="checkbox" name="reviewed" ${t.reviewed?'checked':''}> Mark this trade as reviewed</label><div class="form-footer">${button('Cancel','close','secondary')}<button class="btn primary" type="submit">${existing?'Save changes':'Save trade'} ${icon('check')}</button></div></form>`,'',true);preview();
 }
 function preview(){const form=document.getElementById('manual-trade-form'),node=document.getElementById('manual-result-preview');if(!form||!node)return;const field=n=>form.elements.namedItem(n)?.value??'',known=field('pnl').trim()!==''&&Number.isFinite(Number(field('pnl'))),net=Number(field('pnl'))-Number(field('fees')||0),risk=Number(field('risk')),r=known&&risk>0?net/risk:null;node.innerHTML=`<div><span>Net P&L</span><strong class="${known&&net<0?'negative-text':'positive-text'}">${known?money(net,true):'—'}</strong></div><div><span>Realized R</span><strong>${r===null?'—':r.toFixed(2)+'R'}</strong></div><small>Preview only · saved after server validation</small>`;}
 async function submit(form,fields){const error=document.getElementById('manual-form-error'),submit=form.querySelector('button[type="submit"]');if(submit?.disabled)return;if(submit)submit.disabled=true;if(error){error.hidden=true;error.textContent='';}try{const result=await api.save('manual.save',fields,{id:form.dataset.id||undefined});api.close();api.saved(result.trade);api.toast(form.dataset.id?'Manual trade updated.':'Manual trade saved to your cloud journal.');}catch(e){if(error){error.textContent=e.message;error.hidden=false;error.scrollIntoView?.({block:'nearest'});}else api.toast(e.message);}finally{if(submit)submit.disabled=false;}}
 async function action(value){const [type,id]=value.split(':');if(type==='manual-new')return open();if(type==='manual-edit')return open(id);if(type==='manual-tab'){tab=id==='archived'?'archived':'active';api.render();return;}
 const t=[...api.db().trades,...(api.db().deletedManualTrades||[])].find(t=>t.id===id&&t.source==='Manual entry');if(!t||!api.accounts().some(a=>a.id===t.accountId))return;
 if(type==='manual-archive'){api.modal('Archive this manual trade?',`<p>${esc(t.symbol)} · ${money(t.pnl-t.fees,true)} will leave the active journal, calendar, and account goal. You can restore it from Manual trades → Archived.</p>`,button('Cancel','close','secondary')+button('Archive trade','manual-confirm-archive:'+id,'danger','trash'));return;}
 if(type==='manual-confirm-archive'||type==='manual-restore'){await api.save(type==='manual-restore'?'manual.restore':'manual.archive',{revision:t.revision},{id});api.close();api.render();api.toast(type==='manual-restore'?'Manual trade restored.':'Manual trade archived. Restore it from Manual trades → Archived.');}
 }
 function change(event){if(event.target.id!=='manual-account')return false;const a=eligible().find(a=>a.id===event.target.value),form=document.getElementById('manual-trade-form');if(form&&!form.dataset.id){const g=a?.goal?goalProgress(a,api.db().trades):null;form.elements.namedItem('risk').value=g&&!g.complete?g.risk:'';}preview();return true;}
 return {page,open,submit,preview,change,handles:value=>value.startsWith('manual-'),action};
}
